function setStatus(message, type = "info") {
  statusBox.className = "notice " + type;
  statusBox.textContent = message;
}

async function isAdmin(user) {
  if (!user) return false;
  const snap = await getDoc(doc(db, "users", user.uid));
  return snap.exists() && snap.data().role === "admin";
}

async function updateBooks() {
  let count = 0;

  for (const [bookId, slides] of Object.entries(BOOK_SLIDES)) {
    await setDoc(doc(db, "books", bookId), {
      bookSlides: slides,
      slides: slides,
      slideMode: true,
      coverUrl: slides[0]?.imageUrl || "",
      updatedAt: serverTimestamp()
    }, { merge: true });
    count++;
  }

  return count;
}

async function updateCourses() {
  let courseCount = 0;
  let lessonCount = 0;

  for (const [courseId, imageUrl] of Object.entries(COURSE_IMAGES)) {
    await setDoc(doc(db, "courses", courseId), {
      coverUrl: imageUrl,
      slideMode: true,
      updatedAt: serverTimestamp()
    }, { merge: true });

    courseCount++;

    const lessonSnap = await getDocs(query(collection(db, "courseLessons"), where("courseId", "==", courseId)));
    let idx = 0;

    for (const lessonDoc of lessonSnap.docs) {
      idx++;
      await setDoc(doc(db, "courseLessons", lessonDoc.id), {
        imageUrl: imageUrl.replace(".jpg", `-lesson-${idx}.jpg`),
        animation: idx % 3 === 1 ? "fade-up" : idx % 3 === 2 ? "zoom-in" : "fade-left",
        layout: "image-top",
        slideMode: true,
        updatedAt: serverTimestamp()
      }, { merge: true });

      lessonCount++;
    }
  }

  return { courseCount, lessonCount };
}

async function updateKiddies() {
  let count = 0;

  for (const [resourceId, slides] of Object.entries(KIDDIES_SLIDES)) {
    await setDoc(doc(db, "kiddiesResources", resourceId), {
      kiddiesSlides: slides,
      slides: slides,
      slideMode: true,
      coverUrl: slides[0]?.imageUrl || "",
      updatedAt: serverTimestamp()
    }, { merge: true });
    count++;
  }

  return count;
}

async function runSeed() {
  if (!adminReady) throw new Error("Admin access not verified.");

  setStatus("Updating books with chapter slides and images...", "info");
  const books = await updateBooks();

  setStatus("Updating course lessons with slide images...", "info");
  const courseResult = await updateCourses();

  setStatus("Updating Kiddies resources with slide images...", "info");
  const kiddies = await updateKiddies();

  return {
    books,
    courses: courseResult.courseCount,
    courseLessons: courseResult.lessonCount,
    kiddies
  };
}

onAuthStateChanged(auth, async user => {
  if (!user) {
    setStatus("Please login as admin first, then refresh this page.", "error");
    seedBtn.disabled = true;
    return;
  }

  try {
    adminReady = await isAdmin(user);

    if (!adminReady) {
      setStatus("Access denied. Admin role required.", "error");
      seedBtn.disabled = true;
      return;
    }

    setStatus("Admin verified. You can install slide images.", "success");
    seedBtn.disabled = false;
  } catch (error) {
    console.error(error);
    setStatus("Admin check failed. " + (error.message || ""), "error");
  }
});

seedBtn.addEventListener("click", async () => {
  seedBtn.disabled = true;

  try {
    const result = await runSeed();

    setStatus(
      `Done.\n\nUpdated with slide images:\nBooks: ${result.books}\nCourses: ${result.courses}\nCourse Lessons: ${result.courseLessons}\nKiddies Resources: ${result.kiddies}`,
      "success"
    );
  } catch (error) {
    console.error(error);
    setStatus(error.message || "Slide image seed failed.", "error");
    seedBtn.disabled = false;
  }
});
